/*
 * Abhi 3D web pet: add <script src="abhi3d-pet.js"></script> to any page.
 * Options on the script tag: data-scale="1.2", data-sleep-after="30" (seconds, 0 = never), data-side="left",
 *   data-mount="#selector" (render inside that element instead of floating; dragging is then disabled).
 * API: AbhiPet.play(pose), .feed('chai'|'dumplings'|'cookie'), .sleep(), .wake(), .hide(), .show()
 */
(function () {
  if (window.AbhiPet) return;
  var SHEET = 'data:image/png;base64,', LOOK = 'data:image/png;base64,', HAND = 'data:image/png;base64,';
  var CELL = 127;
  var STATES = {
    idle: [0, 4, 1800], running: [1, 4, 560], 'running-right': [2, 8, 720], 'running-left': [3, 8, 720],
    waving: [4, 4, 1000], 'skill-review': [5, 4, 1600], 'skill-orchestrate': [6, 4, 1300],
    'skill-paperwork': [7, 4, 1500], 'skill-research': [8, 4, 1600], 'skill-video': [9, 4, 1600],
    hungry: [10, 4, 1400], 'eat-dumplings': [11, 4, 1000], 'eat-chai': [12, 4, 1400], 'eat-cookie': [13, 4, 1000],
    full: [14, 4, 1200], bed: [15, 4, 2400], 'bed-wake': [16, 4, 2000], brush: [17, 4, 1600],
    'bed-pull': [18, 4, 2800], riding: [19, 4, 480]
  };
  var LOOK_CFG = { cols: 5, rows: 3, face: [63, 50], tickle: { row: 3, frames: 5, ms: 900, belly: [63, 87] } };
  var LOOK_NEAR = 200, LOOK_FAR = 240, TICKLE_R = 18, TICKLE_LINGER = 800;
  var EAT_MS = 3200, FULL_MS = 2400, BRUSH_MS = 3200, HUNGRY_AFTER = 3 * 3600 * 1000, PULL_DRAG = 10;
  var RUN_POSES = { running: 1, 'running-right': 1, 'running-left': 1, riding: 1 };
  var LEAN = { 'running-right': 6, 'running-left': -6 };

  var tag = document.currentScript || {};
  var ds = tag.dataset || {};
  var scale = parseFloat(ds.scale) || 1;
  var sleepAfter = ds.sleepAfter !== undefined ? parseFloat(ds.sleepAfter) * 1000 : 30000;
  var side = ds.side === 'left' ? 'left' : 'right';
  var mountSel = ds.mount || '';

  function store(k, v) {
    try { if (v === undefined) return localStorage.getItem('abhipet.' + k); localStorage.setItem('abhipet.' + k, v); } catch (e) { return null; }
  }
  function img(src) { var i = new Image(); i.src = src; return i; }
  var sheet = img(SHEET), lookSheet = img(LOOK);

  var W = CELL, H = CELL + 14;
  var box = document.createElement('div');
  box.setAttribute('aria-label', 'Abhi 3D pet');
  box.style.cssText = (mountSel ? 'position:relative;z-index:1;margin:0 auto;' : 'position:fixed;z-index:2147483000;bottom:16px;' + side + ':16px;') +
    'width:' + W * scale + 'px;height:' + H * scale + 'px;touch-action:none;user-select:none;-webkit-user-select:none;';
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block;';
  var clock = document.createElement('div');
  clock.style.cssText = 'position:absolute;left:50%;top:0;transform:translateX(-50%);padding:1px 8px;border-radius:10px;' +
    'background:rgba(22,26,36,.8);color:#e8ecf4;font:600 ' + 11 * scale + 'px system-ui,sans-serif;opacity:0;transition:opacity .6s;pointer-events:none;';
  box.appendChild(canvas); box.appendChild(clock);
  var ctx = canvas.getContext('2d');
  var dpr = 1;
  function resize() {
    dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(W * scale * dpr); canvas.height = Math.round(H * scale * dpr);
  }

  var saved = mountSel ? [] : (store('pos') || '').split(',');
  if (saved.length === 2) { box.style.left = saved[0] + 'px'; box.style.top = saved[1] + 'px'; box.style.bottom = box.style.right = 'auto'; }

  // Pet state
  var pose = 'idle', poseStart = 0, poseLoops = 0;
  var meal = null, mealStart = 0;
  var inBed = false, wakeStart = -1e9, brushing = false, pullStart = -1e9;
  var fedAt = parseFloat(store('fed')) || Date.now();
  var lastActive = performance.now();
  var mouse = { x: -1e4, y: -1e4 }, tickleUntil = 0, lookCell = null, night = 0;
  var drag = null;

  function now() { return performance.now(); }
  function hungry() { return Date.now() - fedAt > HUNGRY_AFTER; }

  // What to draw: a meal, waking up, brushing, bed, hunger, then the chosen pose.
  function shown(t) {
    inBed = false;
    if (meal) {
      var m = t - mealStart;
      if (m < EAT_MS) return meal;
      if (m < EAT_MS + FULL_MS) return 'full';
      meal = null;
    }
    var w = t - wakeStart;
    if (w < STATES['bed-wake'][2]) return 'bed-wake';
    if (brushing) {
      if (w < STATES['bed-wake'][2] + BRUSH_MS) return 'brush';
      brushing = false;
      fedAt = Date.now() - HUNGRY_AFTER - 60000; store('fed', fedAt);
    }
    if (poseLoops && t - poseStart > poseLoops * STATES[pose][2]) { pose = 'idle'; poseLoops = 0; }
    var idle = pose === 'idle';
    if (idle && !hungry() && sleepAfter > 0 && t - lastActive > sleepAfter) {
      inBed = true;
      return t - pullStart < STATES['bed-pull'][2] ? 'bed-pull' : 'bed';
    }
    if (idle && hungry()) return 'hungry';
    return pose;
  }

  function play(p, loops) {
    if (!STATES[p]) return;
    if (inBed) wake(false);
    pose = p; poseStart = now(); poseLoops = loops === undefined ? (p === 'idle' ? 0 : 3) : loops;
    lastActive = now();
  }
  function wake(byUser) {
    if (!inBed) return;
    inBed = false; brushing = !!byUser; wakeStart = now(); lastActive = now();
  }
  function feed(food) {
    var key = 'eat-' + String(food || 'dumplings').replace(/^eat-/, '');
    if (!STATES[key]) return;
    brushing = false; meal = key; mealStart = now(); lastActive = now();
    fedAt = Date.now(); store('fed', fedAt);
  }
  function sleep() { pose = 'idle'; poseLoops = 0; meal = null; lastActive = -1e9; fedAt = Math.max(fedAt, Date.now() - HUNGRY_AFTER + 60000); }

  function petRect() { return box.getBoundingClientRect(); }
  // Cursor position in sprite pixels (0..127).
  function local(x, y) { var r = petRect(); return [(x - r.left) / scale, (y - r.top) / scale - (H - CELL)]; }

  function frame() {
    var t = now();
    var p = shown(t);
    var st = STATES[p];
    var elapsed = (p === 'bed-wake') ? t - wakeStart : (p === 'bed-pull') ? t - pullStart :
      (meal && p === meal) ? t - mealStart : t;
    var f = Math.floor((elapsed % st[2]) / (st[2] / st[1]));
    var src = [f * CELL, st[0] * CELL, sheet];

    // Tickle beats looking; neither happens in bed, mid-meal or mid-drag.
    var lp = local(mouse.x, mouse.y);
    var onBelly = false;
    if (!inBed && !meal && !(drag && drag.moved)) {
      var b = LOOK_CFG.tickle.belly;
      onBelly = Math.hypot(lp[0] - b[0], lp[1] - b[1]) < TICKLE_R;
      if (onBelly) tickleUntil = t + TICKLE_LINGER;
    }
    box.style.cursor = onBelly ? 'url(' + HAND + ') 0 14, pointer' : (inBed ? 'grab' : 'default');
    lookCell = null;
    if (t < tickleUntil) {
      var tk = LOOK_CFG.tickle;
      src = [Math.floor((t % tk.ms) / (tk.ms / tk.frames)) * CELL, tk.row * CELL, lookSheet];
    } else if ((p === 'idle' || p === 'waving') && !drag) {
      var dx = lp[0] - LOOK_CFG.face[0], dy = lp[1] - LOOK_CFG.face[1], d = Math.hypot(dx, dy) * scale;
      if (d < LOOK_NEAR || (frame.looking && d < LOOK_FAR)) {
        var c = Math.round((Math.max(-1, Math.min(1, dx / 100)) + 1) / 2 * (LOOK_CFG.cols - 1));
        var r = Math.round((Math.max(-1, Math.min(1, dy / 100)) + 1) / 2 * (LOOK_CFG.rows - 1));
        src = [c * CELL, r * CELL, lookSheet]; lookCell = 1;
      }
    }
    frame.looking = !!lookCell;

    night += ((inBed ? 1 : 0) - night) * 0.05;
    draw(src, p, t);
    clock.textContent = new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    clock.style.opacity = inBed ? 1 : 0;
    requestAnimationFrame(frame);
  }

  function draw(src, p, t) {
    ctx.setTransform(dpr * scale, 0, 0, dpr * scale, 0, 0);
    ctx.clearRect(0, 0, W, H);
    var ground = H - 6, lift = 0, stretch = 1, lean = 0;
    if (RUN_POSES[p] && src[2] === sheet) {
      // Two bounces per loop, squashed on landing and stretched at the top.
      var ph = Math.abs(Math.sin(Math.PI * 2 * (t % STATES[p][2]) / STATES[p][2]));
      lift = ph * 4; stretch = 1 + (ph - 0.5) * 0.07; lean = LEAN[p] || 0;
    }
    ctx.fillStyle = 'rgba(0,0,0,' + (0.18 - lift * 0.02) + ')';
    ctx.beginPath(); ctx.ellipse(W / 2, ground, 34 - lift * 2, 5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.save();
    ctx.translate(W / 2, ground - lift + 6);
    ctx.rotate(lean * Math.PI / 180);
    ctx.scale(1 / stretch, stretch);
    ctx.translate(-W / 2, -(CELL));
    ctx.imageSmoothingEnabled = true;
    if (src[2].complete && src[2].naturalWidth) ctx.drawImage(src[2], src[0], src[1], CELL, CELL, 0, 0, CELL, CELL);
    ctx.restore();
    if (night > 0.01) nightTint();
  }

  // Night: darker, cooler colours; blue keeps more of its light than red and green.
  function nightTint() {
    var n = night, d = ctx.getImageData(0, 0, canvas.width, canvas.height), a = d.data;
    var rk = 1 - 0.5 * n, gk = 1 - 0.45 * n, bk = 1 - 0.2 * n, badd = 0.04 * n * 255;
    for (var i = 0; i < a.length; i += 4) {
      if (!a[i + 3]) continue;
      a[i] *= rk; a[i + 1] *= gk; a[i + 2] = a[i + 2] * bk + badd;
    }
    ctx.putImageData(d, 0, 0);
    ctx.setTransform(dpr * scale, 0, 0, dpr * scale, 0, 0);
    ctx.globalAlpha = n;
    ctx.fillStyle = '#f5e7a8';
    ctx.beginPath(); ctx.arc(112, 30, 7, 0, Math.PI * 2); ctx.fill();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath(); ctx.arc(115, 27, 6, 0, Math.PI * 2); ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#fff';
    [[14, 30], [26, 44], [100, 52], [8, 58]].forEach(function (s, i) {
      ctx.globalAlpha = n * (0.5 + 0.5 * Math.sin(now() / 500 + i)); ctx.fillRect(s[0], s[1], 2, 2);
    });
    ctx.globalAlpha = 1;
  }

  // Mouse: drag moves the pet (in bed it pulls the blanket), a click waves or turns the light on.
  function markActive() { if (!inBed) lastActive = now(); }
  document.addEventListener('pointermove', function (e) { mouse.x = e.clientX; mouse.y = e.clientY; markActive(); }, { passive: true });
  document.addEventListener('keydown', markActive);
  document.addEventListener('scroll', markActive, { passive: true });
  box.addEventListener('pointerdown', function (e) {
    if (e.button !== 0) return;
    var r = petRect();
    drag = { x: e.clientX, y: e.clientY, ox: e.clientX - r.left, oy: e.clientY - r.top, moved: false, pulled: false };
    box.setPointerCapture(e.pointerId);
  });
  box.addEventListener('pointermove', function (e) {
    if (!drag) return;
    var dist = Math.abs(e.clientX - drag.x) + Math.abs(e.clientY - drag.y);
    if (dist > 3) drag.moved = true;
    if (inBed) {
      if (!drag.pulled && dist > PULL_DRAG) { drag.pulled = true; pullStart = now(); }
      return;
    }
    if (!drag.moved || mountSel) return;
    var x = Math.max(0, Math.min(innerWidth - W * scale, e.clientX - drag.ox));
    var y = Math.max(0, Math.min(innerHeight - H * scale, e.clientY - drag.oy));
    box.style.left = x + 'px'; box.style.top = y + 'px'; box.style.right = box.style.bottom = 'auto';
  });
  box.addEventListener('pointerup', function () {
    if (!drag) return;
    if (!drag.moved) { if (inBed) wake(true); else if (!meal && now() >= tickleUntil) play('waving'); }
    else if (!inBed && !mountSel) { var r = petRect(); store('pos', Math.round(r.left) + ',' + Math.round(r.top)); }
    drag = null;
  });

  // Right-click menu
  var menu = document.createElement('div');
  menu.style.cssText = 'position:fixed;z-index:2147483001;display:none;min-width:170px;padding:4px;border-radius:8px;' +
    'background:#fff;color:#1b1f27;box-shadow:0 8px 24px rgba(0,0,0,.2);font:13px system-ui,sans-serif;';
  if (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches) { menu.style.background = '#2b2f37'; menu.style.color = '#eef1f6'; }
  function item(label, fn) {
    var b = document.createElement('div');
    b.textContent = label; b.setAttribute('role', 'menuitem');
    b.style.cssText = 'padding:6px 10px;border-radius:5px;cursor:pointer;';
    b.onmouseenter = function () { b.style.background = 'rgba(127,127,127,.18)'; };
    b.onmouseleave = function () { b.style.background = ''; };
    b.onclick = function () { menu.style.display = 'none'; fn(); };
    return b;
  }
  function openMenu(e) {
    e.preventDefault();
    menu.innerHTML = '';
    if (inBed) menu.appendChild(item('💡 Turn on light', function () { wake(true); }));
    else {
      [['🥟 Dumplings', 'dumplings'], ['☕ Chai', 'chai'], ['🍪 Cookie', 'cookie']].forEach(function (f) {
        menu.appendChild(item(f[0], function () { feed(f[1]); }));
      });
      menu.appendChild(item('👋 Wave', function () { play('waving'); }));
      menu.appendChild(item('🏍️ Ride bike', function () { play('riding', 6); }));
      menu.appendChild(item('🏃 Run', function () { play('running', 6); }));
      menu.appendChild(item('😴 Go to bed', sleep));
    }
    menu.appendChild(item('✕ Hide pet', hide));
    menu.style.display = 'block';
    menu.style.left = Math.min(e.clientX, innerWidth - 180) + 'px';
    menu.style.top = Math.min(e.clientY, innerHeight - menu.offsetHeight - 8) + 'px';
  }
  box.addEventListener('contextmenu', openMenu);
  document.addEventListener('pointerdown', function (e) { if (!menu.contains(e.target)) menu.style.display = 'none'; });

  function hide() { box.style.display = 'none'; }
  function show() { box.style.display = 'block'; }

  function mount() {
    (mountSel && document.querySelector(mountSel) || document.body).appendChild(box); document.body.appendChild(menu);
    resize(); window.addEventListener('resize', resize);
    requestAnimationFrame(frame);
  }
  if (document.body) mount(); else document.addEventListener('DOMContentLoaded', mount);

  window.AbhiPet = {
    play: play, feed: feed, sleep: sleep, show: show, hide: hide,
    wake: function () { wake(true); }, poses: Object.keys(STATES)
  };
})();
